solution.code:
def arus(v, r):
    """Arus (A) = tegangan / hambatan."""
    return v / r


def daya(v, i):
    """Daya (W) = tegangan x arus."""
    return v * i


def hambatan_seri(daftar):
    """Jumlah semua hambatan."""
    return sum(daftar)


def hambatan_paralel(daftar):
    """1 / jumlah kebalikan semua hambatan."""
    return 1 / sum(1 / x for x in daftar)


def warna_ke_ohm(g1, g2, pengali):
    """Nilai ohm dari tiga gelang, memakai DIGIT."""
    return (DIGIT[g1] * 10 + DIGIT[g2]) * 10 ** DIGIT[pengali]


def resistor_led(vs, vled, i):
    """(vs - vled) / i, i dalam ampere."""
    return (vs - vled) / i


def nilai_standar(r):
    """Nilai E12 terkecil (kelipatan 1, 10, 100, ...) yang >= r."""
    for dekade in (1, 10, 100, 1000, 10000, 100000):
        for e in E12:
            nilai = e * dekade
            if nilai >= r - 1e-6:
                return nilai


def rencana_led(vs, vled, i_ma):
    """Dictionary r_hitung, r_standar, arus_ma, daya_mw. ValueError bila data tidak masuk akal."""
    if vs <= vled or i_ma <= 0:
        raise ValueError("data tidak masuk akal")
    r_hitung = resistor_led(vs, vled, i_ma / 1000)
    r_standar = nilai_standar(r_hitung)
    i = arus(vs - vled, r_standar)
    return {
        "r_hitung": r_hitung,
        "r_standar": r_standar,
        "arus_ma": round(i * 1000, 1),
        "daya_mw": round(daya(vs - vled, i) * 1000, 1),
    }

